-- Explicit subject-data text policy; financial identities/amounts and audit history remain intact.
BEGIN;
CREATE FUNCTION public.sandy_tenant_financial_redaction_manifest_v1() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT $m${"id":"financial_subject_text_redaction_v1","format_version":"1.0.0","project_ref":"zmqlyygzqoidkcwdysok","complete_tenant_coverage":false,"financial_records_preserved":true,"external_provider_assets_included":false,"restore_supported":false,"retained_control_copies":true,"maximum_records_per_policy":1000,"maximum_source_row_bytes":16777216,"replacement_text":"[redacted:subject-data-request]","resources":[{"table":"sandy_commerce_accounts","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"code","type":"text","nullable":false},{"name":"name","type":"text","nullable":false},{"name":"kind","type":"text","nullable":false},{"name":"currency","type":"text","nullable":false},{"name":"minor_unit_exponent","type":"integer","nullable":false},{"name":"active","type":"boolean","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"redacted_fields":["name"],"owner_column":"customer_id"},{"table":"sandy_commerce_entries","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"description","type":"text","nullable":false},{"name":"external_reference","type":"text","nullable":false},{"name":"effective_at","type":"timestamp with time zone","nullable":false},{"name":"state","type":"text","nullable":false},{"name":"currency","type":"text","nullable":false},{"name":"minor_unit_exponent","type":"integer","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"reversal_of","type":"uuid","nullable":true},{"name":"posted_at","type":"timestamp with time zone","nullable":true},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"redacted_fields":["description"],"owner_column":"customer_id"},{"table":"sandy_commerce_entry_lines","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"entry_id","type":"uuid","nullable":false},{"name":"account_id","type":"uuid","nullable":false},{"name":"debit_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"credit_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"description","type":"text","nullable":false}],"redacted_fields":["description"],"owner_column":"entry_id","ownership_adapter":"financial_entry_customer"},{"table":"sandy_commerce_statement_lines","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"statement_id","type":"uuid","nullable":false},{"name":"external_reference","type":"text","nullable":false},{"name":"effective_at","type":"timestamp with time zone","nullable":false},{"name":"amount_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"description","type":"text","nullable":false}],"redacted_fields":["description"],"owner_column":"statement_id","ownership_adapter":"financial_statement_customer"},{"table":"sandy_commerce_invoices","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"counterparty_name","type":"text","nullable":false},{"name":"external_reference","type":"text","nullable":false},{"name":"currency","type":"text","nullable":false},{"name":"minor_unit_exponent","type":"integer","nullable":false},{"name":"items","type":"jsonb","nullable":false,"encoding":"strict_invoice_items"},{"name":"subtotal_minor","type":"numeric(30,0)","nullable":false,"encoding":"decimal_integer_string"},{"name":"tax_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"discount_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"total_minor","type":"numeric(30,0)","nullable":false,"encoding":"decimal_integer_string"},{"name":"due_at","type":"timestamp with time zone","nullable":false},{"name":"state","type":"text","nullable":false},{"name":"invoice_number","type":"text","nullable":true},{"name":"version","type":"integer","nullable":false},{"name":"source_message_id","type":"uuid","nullable":true},{"name":"forwarding_status","type":"text","nullable":false},{"name":"payment_status","type":"text","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"redacted_fields":["counterparty_name","items.description"],"owner_column":"customer_id"},{"table":"sandy_commerce_entitlements","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"feature_key","type":"text","nullable":false},{"name":"expires_at","type":"timestamp with time zone","nullable":false},{"name":"revoked_at","type":"timestamp with time zone","nullable":true},{"name":"reason","type":"text","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"redacted_fields":["reason"],"owner_column":"customer_id"}],"retained_categories":["financial_identifiers_and_external_references","amounts_currency_units_and_balance_history","posted_reversal_invoice_numbering_and_versions","commercial_consent_and_entitlement_state","source_relationships_and_record_identity","shared_admission_and_audit_hashes","separate_product_and_commerce_control_payload_copies"],"financial_source_manifest_sha256":"ccac4b06066c1f9ed0613d47e00e6abc85075063a29ce26f9b82f11fe43eaeb1","schema_sha256":"a1348b7541435389e1358600ce0a90c4a494b7159d5bd6dd12e5d18b32618609","manifest_sha256":"b3dfae14aac192f72c4c09e3f65a4184c78ef218b1e912aef5a9eeb61a357c63"}$m$::jsonb $$;
CREATE FUNCTION public.sandy_tenant_financial_redaction_schema_sha256() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$WITH tables AS(SELECT t.item,c.oid,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relkind FROM jsonb_array_elements(public.sandy_tenant_financial_redaction_manifest_v1()->'resources')t(item) JOIN pg_namespace n ON n.nspname='public' JOIN pg_class c ON c.relnamespace=n.oid AND c.relname=t.item->>'table'),document AS(SELECT jsonb_agg(jsonb_build_object('table',t.item->>'table','owner',pg_get_userbyid(t.relowner),'rls',t.relrowsecurity,'force_rls',t.relforcerowsecurity,'kind',t.relkind,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT coalesce(jsonb_agg(pg_get_constraintdef(k.oid) ORDER BY k.conname),'[]'::jsonb) FROM pg_constraint k WHERE k.conrelid=t.oid),'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('definition',pg_get_triggerdef(g.oid),'enabled',g.tgenabled) ORDER BY g.tgname),'[]'::jsonb) FROM pg_trigger g WHERE g.tgrelid=t.oid AND NOT g.tgisinternal)) ORDER BY t.item->>'table') AS value FROM tables t) SELECT encode(extensions.digest(value::text,'sha256'),'hex') FROM document$$;
CREATE TABLE public.sandy_tenant_financial_redaction_policies(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,
 resource text NOT NULL CHECK(resource IN('sandy_commerce_accounts','sandy_commerce_entries','sandy_commerce_entry_lines','sandy_commerce_statement_lines','sandy_commerce_invoices','sandy_commerce_entitlements')),
 record_ids uuid[] NOT NULL CHECK(cardinality(record_ids) BETWEEN 1 AND 1000 AND array_ndims(record_ids)=1),
 manifest_sha256 text NOT NULL,schema_sha256 text NOT NULL,source_sha256 text NOT NULL,
 consent_revision integer NOT NULL,source_cutoff timestamptz NOT NULL,effective_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,
 basis text NOT NULL CHECK(basis IN('subject_data_request','approved_retention_schedule')),policy_reference uuid NOT NULL,
 created_by uuid NOT NULL,source_admission_id uuid NOT NULL UNIQUE REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(expires_at>effective_at),CHECK(isfinite(source_cutoff) AND isfinite(effective_at) AND isfinite(expires_at))
);
CREATE TABLE public.sandy_tenant_financial_redaction_revocations(policy_id uuid PRIMARY KEY REFERENCES public.sandy_tenant_financial_redaction_policies(id) ON DELETE RESTRICT,actor_id uuid NOT NULL,admission_id uuid NOT NULL UNIQUE REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,revoked_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_tenant_financial_redaction_leases(
 transaction_id xid8 NOT NULL,policy_id uuid NOT NULL REFERENCES public.sandy_tenant_financial_redaction_policies(id) ON DELETE RESTRICT,
 admission_id uuid NOT NULL REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,actor_id uuid NOT NULL,
 canonical_arguments text NOT NULL,tenant_id uuid NOT NULL,resource text NOT NULL,record_id uuid NOT NULL,before_sha256 text NOT NULL,after_sha256 text NOT NULL,used_at timestamptz,
 PRIMARY KEY(transaction_id,resource,record_id),UNIQUE(admission_id,resource,record_id)
);
CREATE TABLE public.sandy_tenant_financial_redaction_applications(policy_id uuid PRIMARY KEY REFERENCES public.sandy_tenant_financial_redaction_policies(id) ON DELETE RESTRICT,admission_id uuid NOT NULL UNIQUE REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,record_count integer NOT NULL,changed_count integer NOT NULL,before_sha256 text NOT NULL,after_sha256 text NOT NULL,applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_tenant_financial_redaction_receipts(admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,policy_id uuid NOT NULL REFERENCES public.sandy_tenant_financial_redaction_policies(id) ON DELETE RESTRICT,result jsonb NOT NULL);
CREATE TRIGGER sandy_tenant_financial_policies_immutable BEFORE UPDATE OR DELETE ON public.sandy_tenant_financial_redaction_policies FOR EACH ROW EXECUTE FUNCTION public.sandy_tenant_lifecycle_immutable();
CREATE TRIGGER sandy_tenant_financial_revocations_immutable BEFORE UPDATE OR DELETE ON public.sandy_tenant_financial_redaction_revocations FOR EACH ROW EXECUTE FUNCTION public.sandy_tenant_lifecycle_immutable();
CREATE TRIGGER sandy_tenant_financial_applications_immutable BEFORE UPDATE OR DELETE ON public.sandy_tenant_financial_redaction_applications FOR EACH ROW EXECUTE FUNCTION public.sandy_tenant_lifecycle_immutable();
CREATE TRIGGER sandy_tenant_financial_redaction_receipts_immutable BEFORE UPDATE OR DELETE ON public.sandy_tenant_financial_redaction_receipts FOR EACH ROW EXECUTE FUNCTION public.sandy_tenant_lifecycle_immutable();
ALTER TABLE public.sandy_tenant_financial_redaction_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_tenant_financial_redaction_revocations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_tenant_financial_redaction_leases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_tenant_financial_redaction_applications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sandy_tenant_financial_redaction_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_tenant_financial_redaction_policies,public.sandy_tenant_financial_redaction_revocations,public.sandy_tenant_financial_redaction_leases,public.sandy_tenant_financial_redaction_applications,public.sandy_tenant_financial_redaction_receipts FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.sandy_tenant_financial_redaction_manifest_v1(),public.sandy_tenant_financial_redaction_schema_sha256() FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
